import{_ as i,o as a,c as e,ag as t}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/developers/api-quickstart-key-created.png",l="/docs/images/developers/api-quickstart-key-created-mobile.png",h="/docs/images/developers/api-quickstart-sheet.png",g=JSON.parse('{"title":"Make your first API call","description":"Create an API key, list your documents, and write cells into a new sheet with curl.","frontmatter":{"title":"Make your first API call","description":"Create an API key, list your documents, and write cells into a new sheet with curl.","type":"tutorial"},"headers":[],"relativePath":"developers/api/quickstart.md","filePath":"developers/api/quickstart.md"}'),o={name:"developers/api/quickstart.md"};function p(k,s,r,d,c,u){return a(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="make-your-first-api-call" tabindex="-1">Make your first API call <a class="header-anchor" href="#make-your-first-api-call" aria-label="Permalink to &quot;Make your first API call&quot;">​</a></h1><p>In this tutorial you create an API key, list your documents, and write a small sales table into a new sheet with <code>curl</code>. It takes about 10 minutes.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need to be a member of a Wafflebase workspace.</li><li>You need <code>curl</code> and <a href="https://jqlang.org/" target="_blank" rel="noreferrer"><code>jq</code></a> in a terminal.</li><li>On a self-hosted server, replace <code>https://api.wafflebase.io</code> with your API origin.</li></ul></div><h2 id="_1-create-an-api-key" tabindex="-1">1. Create an API key <a class="header-anchor" href="#_1-create-an-api-key" aria-label="Permalink to &quot;1. Create an API key&quot;">​</a></h2><ol><li>Open your workspace in the browser and click <strong>Settings</strong> in the sidebar.</li><li>In the <strong>API keys</strong> section, click <strong>Create API key</strong>.</li><li>Enter a name, such as <code>Quickstart</code>, and click <strong>Create</strong>.</li><li>In the <strong>API key created</strong> dialog, click the copy icon (<strong>Copy API key</strong>), then click <strong>Done</strong>.</li></ol><p>The key starts with <code>wfb_</code> and is shown only once. If you lose it, revoke it and create another.</p><p><img src="'+n+'" alt="The API key created dialog showing a new wfb_ key with its copy button"></p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>The <strong>Settings</strong> page stacks its sections. <strong>Create API key</strong> sits under the <strong>API keys</strong> heading instead of beside it.</p><p><img src="'+l+`" alt="The API keys section on a phone with Create API key under the heading"></p><h2 id="_2-set-up-your-shell" tabindex="-1">2. Set up your shell <a class="header-anchor" href="#_2-set-up-your-shell" aria-label="Permalink to &quot;2. Set up your shell&quot;">​</a></h2><ol><li><p>Note your workspace slug. It is the part after <code>/w/</code> in the address bar, for example <code>acme</code> in <code>/w/acme/settings</code>.</p></li><li><p>Set three variables in your terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WFB_API</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://api.wafflebase.io/api/v1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WFB_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wfb_paste_your_key_here</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">acme</span></span></code></pre></div></li></ol><p>Every command below uses these variables.</p><h2 id="_3-list-your-documents" tabindex="-1">3. List your documents <a class="header-anchor" href="#_3-list-your-documents" aria-label="Permalink to &quot;3. List your documents&quot;">​</a></h2><ol><li><p>Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WFB_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WFB_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/workspaces/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/documents&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.[] | {id, title, type}&#39;</span></span></code></pre></div></li></ol><p>You see one object per document in the workspace. An empty workspace prints nothing.</p><p>If you get <code>401</code>, check that <code>WFB_KEY</code> holds the whole key. If you get <code>403 API key is not scoped to this workspace</code>, the key was created in a different workspace than <code>WS</code>.</p><h2 id="_4-create-a-sheet-and-write-cells" tabindex="-1">4. Create a sheet and write cells <a class="header-anchor" href="#_4-create-a-sheet-and-write-cells" aria-label="Permalink to &quot;4. Create a sheet and write cells&quot;">​</a></h2><ol><li><p>Create a sheet and keep its ID:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DOC</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WFB_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;title&quot;: &quot;Q1 Sales&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WFB_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/workspaces/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/documents&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $DOC</span></span></code></pre></div></li><li><p>Write a header row, three rows of data, and a total in one request:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WFB_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;cells&quot;: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;A1&quot;: {&quot;value&quot;: &quot;Rep&quot;, &quot;style&quot;: {&quot;b&quot;: true}},</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;B1&quot;: {&quot;value&quot;: &quot;Revenue&quot;, &quot;style&quot;: {&quot;b&quot;: true}},</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;A2&quot;: &quot;Alice&quot;, &quot;B2&quot;: &quot;12500&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;A3&quot;: &quot;Bob&quot;,   &quot;B3&quot;: &quot;9800&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;A4&quot;: &quot;Carol&quot;, &quot;B4&quot;: &quot;14200&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;A5&quot;: {&quot;value&quot;: &quot;Total&quot;, &quot;style&quot;: {&quot;b&quot;: true}},</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;B5&quot;: &quot;=SUM(B2:B4)&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WFB_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/workspaces/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/documents/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOC</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/tabs/tab-1/cells&quot;</span></span></code></pre></div></li></ol><p>The response is <code>{&quot;updated&quot;:10}</code>. The first write to a new sheet creates its one tab, with the ID <code>tab-1</code>. A plain string is stored as a value, and a string that starts with <code>=</code> is stored as a formula.</p><h2 id="_5-read-the-cells-back" tabindex="-1">5. Read the cells back <a class="header-anchor" href="#_5-read-the-cells-back" aria-label="Permalink to &quot;5. Read the cells back&quot;">​</a></h2><ol><li><p>List the sheet&#39;s tabs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WFB_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WFB_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/workspaces/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/documents/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOC</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/tabs&quot;</span></span></code></pre></div><p>You see <code>[{&quot;id&quot;:&quot;tab-1&quot;,&quot;name&quot;:&quot;Sheet1&quot;,&quot;type&quot;:&quot;sheet&quot;}]</code>.</p></li><li><p>Read the range you wrote:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WFB_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WFB_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/workspaces/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/documents/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOC</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/tabs/tab-1/cells?range=A1:B5&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.[] | {ref, value, formula}&#39;</span></span></code></pre></div><p>Each cell comes back with its <code>ref</code>, <code>value</code>, <code>formula</code>, and <code>style</code>. The API stores formulas but does not evaluate them, so <code>B5</code> comes back with <code>formula</code> <code>=SUM(B2:B4)</code> and an empty <code>value</code>.</p></li><li><p>Open the workspace in your browser and open <strong>Q1 Sales</strong>.</p></li></ol><p>The sheet shows the table you wrote, with a bold header row and a <strong>Total</strong> row. Opening the sheet does not recalculate formulas written through the API, so the <strong>Total</strong> cell stays blank until you edit one of the cells it sums, such as <code>B2</code>. Then it shows <code>36500</code>.</p><p><img src="`+h+'" alt="The Q1 Sales sheet written through the API, with a bold header row and a Total row"></p><h2 id="what-you-learned" tabindex="-1">What you learned <a class="header-anchor" href="#what-you-learned" aria-label="Permalink to &quot;What you learned&quot;">​</a></h2><ul><li>An API key acts as you, in one workspace.</li><li><code>PATCH .../cells</code> writes many cells at once, with values, formulas, and styles.</li><li>The API stores formulas; the editor calculates their results.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/developers/api/sheets.html">Sheets</a> for every cell, tab, and row endpoint.</li><li><a href="/docs/developers/api/">REST API overview</a> for scopes, errors, and rate limits.</li><li><a href="/docs/developers/api/content.html">Document content</a> to write docs, notes, and decks.</li><li><a href="/docs/developers/cli/sheets.html#import-and-export-csv-or-json">Use the CLI</a> to load a CSV file into a sheet in one command.</li></ul>',28)])])}const y=i(o,[["render",p]]);export{g as __pageData,y as default};
